<style>
    .loader {
        position: fixed;
        display: flex;
        justify-items: center;
        justify-content: center;
        align-items: center;
        left: 0;
        top: 0;
        background: #f7f7ed;
        background-image: radial-gradient(#ccc 1.2px, transparent 1.2px);
        background-size: 30px 30px;
        width: 100%;
        height: 100%;
        /* z-index: 9999; */
    }

    .loader svg {
        /* filter: drop-shadow(0 0 5px rgba(186, 186, 179, 0.3)) drop-shadow(0 0 10px rgba(186, 186, 179, 0.3)); */

        /* transform: scale(0.09); */
    }


    #svg path {
        fill-opacity: 0;
        stroke-width: 10;
        stroke: #babab3;
        stroke-dasharray: 960;
        stroke-dashoffset: 960;
        animation: tracefill 2s linear infinite;
    }

    @keyframes tracefill {
        0% {
            stroke-dashoffset: 0;
            fill-opacity: 1;
            /* Show the original fill color */
        }

        30% {
            fill-opacity: 0;
            /* Hide the fill */
        }

        40% {
            stroke-dashoffset: 960;
            fill-opacity: 0;
        }

        80% {
            stroke-dashoffset: 1920;
            fill-opacity: 1;
        }

        100% {
            stroke-dashoffset: 1920;
            fill-opacity: 1;
            stroke: transparent;
        }
    }

    .fade {
        animation: fadeOut 1.5s ease forwards infinite;
    }

    @keyframes fadeOut {
        to {
            opacity: 0;
            visibility: hidden;
        }
    }
</style>
<script>
    document.addEventListener("DOMContentLoaded", async () => {

        const waitForContainer = () => {
            return new Promise((resolve) => {
                const container = document.querySelector(".container");
                if (!container) return resolve();

                // Jika tidak ada gambar, resolve langsung
                // const images = container.querySelectorAll("img");
                const images = container.querySelectorAll(
                    "img:not([loading='lazy']):not([decoding='async'])"
                );
                if (images.length === 0) return resolve();

                let loaded = 0;
                images.forEach((img) => {
                    if (img.complete) {
                        loaded++;
                        if (loaded === images.length) resolve();
                    } else {
                        img.addEventListener("load", () => {
                            loaded++;
                            if (loaded === images.length) resolve();
                        });
                        img.addEventListener("error", () => {
                            loaded++;
                            if (loaded === images.length) resolve();
                        });
                    }
                });
            });
        };

        await waitForContainer();

        document.querySelector(".svg")?.classList.add("fade");
        // gsap.registerPlugin(ScrollTrigger, ScrollToPlugin);

        // Posisi awal (off-screen kanan)
        gsap.set(".container", {
            left: "100%",
            scale: 0.5,
            visibility: "visible"
        });

        // GSAP animasi masuk
        gsap.to(".container", {
            duration: 2,
            left: "50%",
            scale: 0.5,
            transform: "translateX(-50%)",
            ease: "power4.inOut",
            delay: 0.3,
        });

        // Loader menghilang
        gsap.to(".loader", {
            duration: 2.5,
            scale: 0,
            ease: "power4.inOut",
            delay: 2,
        });

        // Container full scale
        gsap.to(".container", {
            duration: 2,
            scale: 1,
            ease: "power4.inOut",
            delay: 2.5,
            onComplete: () => {
                AOS.init({
                    once: true,
                    mirror: true,
                    // offset: 120,
                });


                setTimeout(() => {
                    AOS.refreshHard(); // forcefully re-calculate positions
                }, 500); // wait a bit after animation
                // console.log("GSAP animation complete!");
                // // Initialize AOS **after** all transitions are done
                // if (typeof AOS !== 'undefined') {
                //     AOS.init({
                //         once: false,
                //         mirror: true,
                //         easing: 'ease-in-out',
                //         // offset: 120,
                //     });

                //         AOS.refresh();
                // }
            }
        });


    });
</script>